contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public function that attempts to call transfer and checks the returned-success behavior
    function run(address contract_address, address[] memory tos, uint[] memory vs) public payable {
        // enforce the same preconditions as the modifier/requirements so the call can proceed to attempt execution
        require(contract_address != address(0x0));
        require(contract_address != address(c));
        require(tos.length > 0);
        require(vs.length > 0);
        require(tos.length == vs.length);

        bool reverted;
        bool ret;
        // call transfer and capture whether it reverted; if it didn't revert capture the returned bool
        try c.transfer(contract_address, tos, vs) returns (bool _r) {
            reverted = false;
            ret = _r;
        } catch {
            reverted = true;
            ret = false; // value unused when reverted == true
        }

        // General property: if the call did not revert, it must have returned true.
        // This asserts that successful execution of transfer always yields true.
        assert(reverted || ret == true);
    }

    receive() external payable { }
}

