contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take the exact parameters of C.transfer and require the preconditions so the call enters its body.
    function run(address contract_address, address[] memory tos, uint[] memory vs) public payable {
        require(contract_address != address(0x0));
        require(contract_address != address(c));
        require(tos.length > 0);
        require(vs.length > 0);
        require(tos.length == vs.length);

        // Record this contract balance before calling c.transfer
        uint before = address(this).balance;

        bool reverted;
        bool ret;
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // If the call did not revert then it must have returned true AND this contract's balance unchanged.
        assert(reverted || (ret == true && address(this).balance == before));
    }

    receive() external payable { }
}

